const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const video=document.querySelector('#city-film'),toggle=document.querySelector('#film-toggle'),sound=document.querySelector('#film-sound');
if(video){new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting&&!reduced)video.play().catch(()=>{});else video.pause()})},{threshold:.25}).observe(video);video.addEventListener('play',()=>toggle.textContent='Ⅱ หยุดวิดีโอ');video.addEventListener('pause',()=>toggle.textContent='▶ เล่นวิดีโอ');toggle.onclick=()=>video.paused?video.play().catch(()=>{}):video.pause();sound.onclick=()=>{video.muted=!video.muted;sound.textContent=video.muted?'เปิดเสียง ↗':'ปิดเสียง ↙';sound.setAttribute('aria-pressed',String(!video.muted))};video.addEventListener('error',()=>document.querySelector('.film-error').hidden=false)}
if(!reduced){document.documentElement.classList.add('motion-enabled');const reveal=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');reveal.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.intro-main,.values>div,.business-card,.investor-header,.financial-grid,.news-item,.sustain-wrap,.film-heading').forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--delay',(i%3)*90+'ms');reveal.observe(el)});
 let queued=false;addEventListener('scroll',()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{const p=scrollY/(document.documentElement.scrollHeight-innerHeight);document.documentElement.style.setProperty('--page-progress',p);const film=document.querySelector('.city-film');if(film){const r=film.getBoundingClientRect();const q=Math.max(0,Math.min(1,1-r.top/innerHeight));film.style.setProperty('--film-reveal',q)}queued=false})},{passive:true});
 document.querySelectorAll('.business-card').forEach(card=>{card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect();card.style.transform=`perspective(1000px) rotateX(${-(e.clientY-r.top-r.height/2)/80}deg) rotateY(${(e.clientX-r.left-r.width/2)/90}deg) translateY(-5px)`});card.addEventListener('pointerleave',()=>card.style.transform='')});}
